<# Runs one bounded native workload from a completed converted-remount checkpoint.
   Any failure preserves the branch; this script never invokes journal recovery. #>
[CmdletBinding(SupportsShouldProcess)]param(
 [string]$ParentResultPath,[string]$ParentResultSha256,[string]$ReviewedSourcesPath,[string]$ReviewedSourcesSha256,
 [ValidateRange(60,900)][int]$BootTimeoutSeconds=300,[ValidateRange(60,900)][int]$NativeTimeoutSeconds=600
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$workspace=Split-Path -Parent $PSScriptRoot
function Get-ASources{@('scripts/Invoke-LabAllocationWorkload.ps1','scripts/Invoke-LabConvertedVerification.ps1','scripts/Invoke-LabRetainedNativeProbe.ps1','scripts/Invoke-LabRetainedPreparation.ps1','lab/Lab.psm1','lab/guest/NativeShadowDisk.cs','lab/guest/NativeMountBoundary.cs','lab/guest/NativeRetainedFixture.cs','lab/guest/NativeRetainedFixture.Windows.cs','lab/guest/NativeConvertedVerification.cs','lab/guest/NativeConvertedVerification.Windows.cs','lab/guest/NativeAllocationWorkload.cs','lab/guest/Invoke-GuestAllocationWorkload.ps1')}
function Read-APin([string]$Path,[string]$Hash,[long]$Maximum=3MB){
 if($Hash-cnotmatch'\A[0-9a-f]{64}\z'){throw 'Independent SHA-256 pin required.'};$p=[IO.Path]::GetFullPath($Path);if(-not$p.StartsWith(($workspace.TrimEnd('\')+'\'),[StringComparison]::OrdinalIgnoreCase)){throw 'Input outside workspace.'};$at=$p
 while($at){$f=Get-Item -LiteralPath $at -Force;if($f.Attributes-band([IO.FileAttributes]::ReparsePoint-bor[IO.FileAttributes]::Compressed-bor[IO.FileAttributes]::Encrypted)){throw 'Ordinary pinned path required.'};$at=[IO.Path]::GetDirectoryName($at)}
 $f=Get-Item -LiteralPath $p;if($f.PSIsContainer-or$f.Length-lt1-or$f.Length-gt$Maximum){throw 'Input size differs.'};$s=New-Object IO.FileStream($p,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 try{$bytes=New-Object byte[] $s.Length;$at=0;while($at-lt$bytes.Length){$n=$s.Read($bytes,$at,$bytes.Length-$at);if($n-le0){throw 'Short input read.'};$at+=$n};$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual-cne$Hash){throw 'Pinned input changed.'};return ,$bytes}finally{$s.Dispose()}
}
function Read-AJson([string]$Path,[string]$Hash,[long]$Maximum=3MB){$text=(New-Object Text.UTF8Encoding($false,$true)).GetString((Read-APin $Path $Hash $Maximum));if($text.Length-gt0-and$text[0]-eq[char]0xfeff){$text=$text.Substring(1)};$text|ConvertFrom-Json}
function Import-AFunctions([byte[]]$Bytes,[string[]]$Names){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput((New-Object Text.UTF8Encoding($false,$true)).GetString($Bytes),[ref]$tokens,[ref]$errors);if($errors.Count){throw 'Reviewed script parse failed.'};foreach($name in $Names){$found=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)|Where-Object Name -CEQ $name);if($found.Count-ne1){throw 'Exact named guard required.'};$def=[regex]::Replace($found[0].Extent.Text,('\Afunction\s+'+[regex]::Escape($name)+'\b'),('function script:'+$name));. ([scriptblock]::Create($def))}}
function Assert-AParent($Value){
 if($Value.schemaVersion-ne1-or$Value.kind-cne'converted-verification-host'-or$Value.mode-cne'clean-remount'-or$Value.status-cne'retained-A-clean-remount-readonly-checkpointed'-or$Value.phase-cne'complete'-or$Value.runId-cne'94f6256f57424ad69147f58199387ee1'-or$Value.vmId-ine'eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c'-or$Value.baselineId-ine'eda059b3-6d50-46bb-bdf4-018b99b5b34f'-or$Value.outcomeCheckpointName-cne('converted-remount-'+$Value.observationId)-or[guid]$Value.outcomeCheckpointId-eq[guid]::Empty){throw 'Completed original-target clean remount required.'}
 foreach($n in @('verificationExported','retainedNativeObservationVerified','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored','mountEvidenceReused')){if($Value.$n-isnot[bool]-or-not$Value.$n){throw 'Incomplete parent result.'}}
 foreach($n in @('transportCompletionUnknown','guestOperationUnknown','sessionPreserved','journalRecoveryRequested','reconstructionPhaseInvoked','rawPayloadWriteRequestsIssued','conversionQualified','bootQualified','mountBoundaryInvoked')){if($Value.$n-isnot[bool]-or$Value.$n){throw 'Uncertain parent result.'}}
 if($Value.handoffResultSha256-cne'e1048284f3729f00720394c69c63670267392fb338205082125de29a60f0dbe1'-or$Value.verificationEvidenceSha256-cnotmatch'\A[0-9a-f]{64}\z'){throw 'Independent closed-handoff/observation binding differs.'}
}
function Assert-AResult($Value,[string]$Id,[string]$InputHash){
 if($Value.schemaVersion-ne1-or$Value.kind-cne'native-allocation-workload'-or$Value.workloadId-cne$Id-or$Value.inputSha256-cne$InputHash-or$Value.status-cne'native-allocation-workload-passed'-or$Value.operationCompletionKnown-isnot[bool]-or-not$Value.operationCompletionKnown){throw 'Completed native workload result required.'}
 $v=$Value.native;foreach($n in @('complete','cleanupComplete')){if($v.$n-isnot[bool]-or-not$v.$n){throw 'Workload cleanup incomplete.'}};foreach($n in @('operationActive','rawPayloadWriteRequestsIssued','conversionQualified','bootQualified')){if($v.$n-isnot[bool]-or$v.$n){throw 'Unexpected workload authority/uncertainty.'}}
 if($v.phase-cne'complete'-or$null-ne$v.error-or$null-ne$v.cleanupError-or$v.fileWriteBytesRequested-ne50MB-or$v.fileBytesWritten-ne50MB-or$v.filesCreated-ne40-or$v.renames-ne16-or$v.truncations-ne32-or$v.deletions-ne40-or(@($v.allocation.stage)-join',')-cne'created,mutated,reallocated,cleaned'){throw 'Workload coverage/byte accounting differs.'}
 foreach($o in @($v.before,$v.after)){if(-not$o.complete-or-not$o.stable-or-not$o.cleanupComplete-or-not$o.privilegeRestored-or$null-ne$o.error-or$null-ne$o.cleanupError-or$o.payloadReadRequests-ne2-or$o.payloadBytesRead-ne131072){throw 'Protected observation incomplete.'}}
 if(@($v.retainedHashes).Count-ne4){throw 'Retained coverage differs.'};foreach($h in $v.retainedHashes){if($h-cne'a8da4df80396fc29486e0cba10fb7525404e8fd56169e6885475789b10f31bb3'){throw 'Retained payload changed.'}}
 $sets=@($v.transitions|Where-Object code -EQ 0x0007c0f4);if(($sets.name-join',')-cne'SetAttributes-2-3,SetAttributes-3-1,SetAttributes-1-0,SetAttributes-0-1,SetAttributes-1-3,SetAttributes-3-2'-or@($sets|Where-Object{-not$_.succeeded-or$_.error-ne0}).Count){throw 'Protection transition coverage differs.'}
}
if(-not$PSCmdlet.ShouldProcess('completed converted-remount checkpoint','Bounded native allocation workload on disposable VM branch')){[pscustomobject]@{DryRun=$true;MaximumFileWriteBytes=64MB;RawPayloadWritesAllowed=$false};return}
$review=Read-AJson $ReviewedSourcesPath $ReviewedSourcesSha256 64KB;$names=@(Get-ASources);if($review.schemaVersion-ne1-or$review.kind-cne'allocation-reviewed-sources'-or@($review.files).Count-ne$names.Count-or@($review.files.path|Select-Object -Unique).Count-ne$names.Count){throw 'Exact reviewed source set required.'};$sources=@{}
foreach($f in $review.files){if($f.path-cnotin$names){throw 'Unexpected source.'};$sources[[IO.Path]::GetFileName($f.path)]=Read-APin (Join-Path $workspace $f.path) $f.sha256 256KB}
Import-AFunctions $sources['Invoke-LabRetainedPreparation.ps1'] @('Assert-RetainedPreparationManifest','Assert-RetainedPreparationVM','Assert-RetainedPreparationBaseline')
Import-AFunctions $sources['Invoke-LabRetainedNativeProbe.ps1'] @('Write-RetainedProbeJson','Copy-RetainedProbePinned','Save-RetainedProbeProgress','Invoke-RetainedProbeCommand','Open-RetainedProbeSession','Assert-RetainedProbeCurrent','Wait-RetainedProbeRestored','Complete-RetainedProbeBaseline','Assert-RetainedProbeCheckpoint','Stop-RetainedProbeGuest','New-RetainedProbeCheckpoint','Copy-RetainedProbeGuestSources')
Import-Module (Join-Path $workspace 'lab/Lab.psm1') -Force;$configuration=Get-LabConfiguration;$manifest=Read-LabManifest -Configuration $configuration -Lane win11;Assert-RetainedPreparationManifest $manifest
$parentPath=Assert-LabPath $ParentResultPath $configuration.Root;$parent=Read-AJson $parentPath $ParentResultSha256;Assert-AParent $parent;$parentRoot=Split-Path -Parent $parentPath
$verification=Read-AJson (Join-Path $parentRoot 'verification/verification.json') $parent.verificationEvidenceSha256
if($verification.status-cne'retained-A-observed-through-protected-ReFS'-or$verification.runId-cne$parent.runId-or$verification.observationId-cne$parent.observationId-or$verification.inputSha256-cne$parent.inputSha256-or$verification.nativeOperationCompletionKnown-isnot[bool]-or-not$verification.nativeOperationCompletionKnown){throw 'Parent native observation differs.'}
$expected=$verification.native.expected;$baselineId=$parent.baselineId;$selectedId=$parent.outcomeCheckpointId;$selectedName=$parent.outcomeCheckpointName
$vm=Assert-RetainedProbeCurrent $baselineId 4GB;Assert-RetainedProbeCheckpoint (Get-ExactLabCheckpoint -VM $vm -Name $selectedName) $selectedId $selectedName;Assert-RetainedPreparationBaseline (Get-ExactLabCheckpoint -VM $vm -Name installed-clean);Assert-LabCapacity (Get-LabCapacity $configuration) -AdditionalBytes 2GB
$id=[guid]::NewGuid().ToString('N');$outcomeName='converted-allocation-'+$id;$outputRoot=Assert-LabPath (Join-Path $configuration.Root ('allocation-workload/win11-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ'))) $configuration.Root
if(Test-Path -LiteralPath $outputRoot){throw 'New host case exists.'};New-Item -ItemType Directory -Path $outputRoot|Out-Null;New-Item -ItemType Directory -Path (Join-Path $outputRoot 'reviewed-sources')|Out-Null
$currentSources=@(foreach($f in $review.files){Copy-RetainedProbePinned (Join-Path $workspace $f.path) (Join-Path $outputRoot ('reviewed-sources/'+[IO.Path]::GetFileName($f.path))) $f.sha256 256KB});$guestSources=@($currentSources|Where-Object name -CIn @('NativeShadowDisk.cs','NativeMountBoundary.cs','NativeRetainedFixture.cs','NativeRetainedFixture.Windows.cs','NativeConvertedVerification.cs','NativeConvertedVerification.Windows.cs','NativeAllocationWorkload.cs','Invoke-GuestAllocationWorkload.ps1'))
foreach($f in $guestSources|Where-Object name -CNotIn @('NativeAllocationWorkload.cs','Invoke-GuestAllocationWorkload.ps1')){$old=@($parent.sourceHashes|Where-Object name -CEQ $f.name);if($old.Count-ne1-or$old[0].sha256-cne$f.sha256){throw 'Frozen proven dependency changed.'}}
Copy-RetainedProbePinned $parentPath (Join-Path $outputRoot 'parent-host-result.json') $ParentResultSha256 3MB|Out-Null;Copy-RetainedProbePinned (Join-Path $parentRoot 'verification/verification.json') (Join-Path $outputRoot 'parent-verification.json') $parent.verificationEvidenceSha256 3MB|Out-Null
$spec=[ordered]@{schemaVersion=1;kind='allocation-workload-input';workloadId=$id;parentVerificationSha256=$parent.verificationEvidenceSha256;handoffSha256='02441be13147333e73778d469ae2c249573239b8a42fd7940d93e57e59bc9d3d';expected=$expected;sources=@($guestSources|Select-Object name,sha256)};$inputPath=Join-Path $outputRoot 'input.json';Write-RetainedProbeJson $inputPath $spec 64KB;$inputHash=(Get-FileHash -LiteralPath $inputPath).Hash.ToLowerInvariant()
$record=[ordered]@{schemaVersion=1;kind='allocation-workload-host';status='started';phase='preflight';workloadId=$id;vmId=$manifest.vmId;baselineId=$baselineId;selectedCheckpointId=$selectedId;selectedCheckpointName=$selectedName;parentResultSha256=$ParentResultSha256;reviewedSourcesSha256=$ReviewedSourcesSha256;sourceHashes=$currentSources;inputSha256=$inputHash;nativeResultSha256=$null;cleanShutdown=$false;outcomeCheckpointCreated=$false;outcomeCheckpointName=$outcomeName;outcomeCheckpointId=$null;baselineRestored=$false;memoryRestored=$false;transportCompletionUnknown=$false;guestOperationUnknown=$false;conversionQualified=$false;bootQualified=$false;rawPayloadWriteRequestsIssued=$false;createdUtc=[DateTime]::UtcNow.ToString('o')}
$credential=Import-Clixml -LiteralPath (Join-Path $configuration.Root 'win11/secrets/guest-credential.xml');if($credential-isnot[Management.Automation.PSCredential]-or$credential.UserName-cne'N2R-WIN11\LabAdmin'){throw 'Exact lab guest credential required.'}
$script:session=$null;$script:transportUnknown=$false;$script:guestOperationUnknown=$false;$script:guestPhaseInFlight=$false;$script:phase='restore-converted-remount';$script:progressIndex=0
try{
 Save-RetainedProbeProgress;Invoke-LabAction -Action Restore -Lane win11 -CheckpointName $selectedName -Confirm:$false|Out-Null;Wait-RetainedProbeRestored $selectedId 8GB|Out-Null;Invoke-LabAction -Action Start -Lane win11 -Confirm:$false|Out-Null
 $script:session=Open-RetainedProbeSession;$policy=Initialize-LabGuestSession -Session $session;if($policy.status-cne'ready'){throw 'Guest session initialization refused.'};Copy-RetainedProbeGuestSources
 $guestRoot='C:\ntfs2refs\allocation-workload\'+$id
 Invoke-RetainedProbeCommand -Arguments @($id) -Body {param($Id);foreach($p in @('C:\ntfs2refs','C:\ntfs2refs\allocation-workload')){if(-not(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p|Out-Null};$f=Get-Item -LiteralPath $p -Force;if(-not$f.PSIsContainer-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'Ordinary workload parent required.'}};$p='C:\ntfs2refs\allocation-workload\'+$Id;if(Test-Path -LiteralPath $p){throw 'New workload directory exists.'};New-Item -ItemType Directory -Path $p|Out-Null}|Out-Null
 Copy-Item -LiteralPath $inputPath -Destination ($guestRoot+'\input.json') -ToSession $session
 $script:phase='native-allocation-workload';$script:guestPhaseInFlight=$true;Save-RetainedProbeProgress;$reply=@(Invoke-RetainedProbeCommand -Timeout $NativeTimeoutSeconds -Arguments @($id,$inputHash) -Body {param($Id,$Hash);& 'C:\ntfs2refs\guest\Invoke-GuestAllocationWorkload.ps1' -WorkloadId $Id -InputSha256 $Hash -Confirm:$false})
 if($reply.Count-ne1-or$reply[0].OperationCompletionKnown-isnot[bool]-or-not$reply[0].OperationCompletionKnown){$script:guestOperationUnknown=$true;throw 'Unknown native workload completion; preserve branch.'};$script:guestPhaseInFlight=$false
 $script:phase='export-native-evidence';Save-RetainedProbeProgress
 $files=@(Invoke-RetainedProbeCommand -Arguments @($guestRoot) -Body {param($Root);$items=@(Get-ChildItem -LiteralPath $Root -Force);if($items.Count-gt410){throw 'Artifact count exceeded.'};foreach($f in $items){if($f.PSIsContainer-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-or$f.Length-gt3MB-or$f.Name-cnotmatch'\A(input\.json|started\.json|result\.json|bitmap-(created|mutated|reallocated|cleaned)\.bin|(before|after)-query-[0-9]{3}\.bin)\z'){throw 'Unexpected workload artifact.'};[pscustomobject]@{name=$f.Name;length=$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName).Hash.ToLowerInvariant()}}})
 if(($files|Measure-Object length -Sum).Sum-gt16MB){throw 'Artifact aggregate exceeded.'};$destRoot=Join-Path $outputRoot 'native';New-Item -ItemType Directory -Path $destRoot|Out-Null
 foreach($f in $files){$dest=Join-Path $destRoot $f.name;Copy-Item -LiteralPath ($guestRoot+'\'+$f.name) -Destination $dest -FromSession $session;if((Get-Item -LiteralPath $dest).Length-ne$f.length-or(Get-FileHash -LiteralPath $dest).Hash.ToLowerInvariant()-cne$f.sha256){throw 'Exported bytes differ.'}}
 $resultFile=@($files|Where-Object name -CEQ 'result.json');if($resultFile.Count-ne1-or$reply[0].ResultPath-cne($guestRoot+'\result.json')-or$reply[0].ResultSha256-cne$resultFile[0].sha256){throw 'Native result reply binding differs.'};$record.nativeResultSha256=$resultFile[0].sha256
 $native=Read-AJson (Join-Path $destRoot 'result.json') $record.nativeResultSha256;Assert-AResult $native $id $inputHash
