 Write-RetainedProbeJson (Join-Path $destRoot 'exported-files.json') $files 128KB
 $script:phase='clean-shutdown';Save-RetainedProbeProgress;Stop-RetainedProbeGuest $selectedId;$record.cleanShutdown=$true;$script:phase='save-outcome';Save-RetainedProbeProgress;$cp=New-RetainedProbeCheckpoint $outcomeName $selectedId;$record.outcomeCheckpointId=[string]$cp.Id;$record.outcomeCheckpointCreated=$true
 $script:phase='restore-baseline';Save-RetainedProbeProgress;Invoke-LabAction -Action Restore -Lane win11 -CheckpointName installed-clean -Confirm:$false|Out-Null;Complete-RetainedProbeBaseline $baselineId;$record.baselineRestored=$true;$record.memoryRestored=$true;$record.status='native-allocation-workload-checkpointed';$script:phase='complete'
}catch{$record.status='failed-preserved';$record['error']=$_.Exception.ToString();$record['errorPosition']=$_.InvocationInfo.PositionMessage;throw}
finally{$record.phase=$script:phase;$record.transportCompletionUnknown=$script:transportUnknown;$record.guestOperationUnknown=($script:guestOperationUnknown-or$script:guestPhaseInFlight);$record['sessionPreserved']=($null-ne$session);$record['finishedUtc']=[DateTime]::UtcNow.ToString('o');Write-RetainedProbeJson (Join-Path $outputRoot 'host-result.json') $record;$credential=$null}
[pscustomobject]@{Status=$record.status;EvidenceDirectory=$outputRoot;OutcomeCheckpointId=$record.outcomeCheckpointId;BaselineRestored=$record.baselineRestored;ConversionQualified=$false}
